structure.mermaidSource:
flowchart TD
  start["Início: Analisar oração e posição do pronome átono"] --> dec_inicia_oracao{"O pronome inicia a oração ou período?"}
  dec_inicia_oracao -- "Sim" --> res_proibido_inicio["Item Errado: Próclise proibida em início de oração"]
  dec_inicia_oracao -- "Não" --> dec_enclise_futuro{"A posição pretendida faz ênclise a verbo no Futuro?"}
  dec_enclise_futuro -- "Sim" --> res_proibido_futuro["Item Errado: Ênclise proibida com verbo no Futuro"]
  dec_enclise_futuro -- "Não" --> dec_enclise_participio{"A posição pretendida faz ênclise a verbo no Particípio?"}
  dec_enclise_participio -- "Sim" --> res_proibido_participio["Item Errado: Particípio nunca admite ênclise"]
  dec_enclise_participio -- "Não" --> dec_palavra_atrativa{"Há palavra atrativa antes do verbo?"}
  dec_palavra_atrativa -- "Sim" --> res_proclise_obrigatoria["Próclise Obrigatória: Elemento atrativo presente"]
  dec_palavra_atrativa -- "Não" --> res_colocacao_facultativa["Colocação Facultativa: Próclise ou Ênclise válidas"]

flowchart TD
  start["1. Identificar Verbo Auxiliar e Principal"] --> dec_terminacao{"Qual é a terminação do Verbo Principal?"}
  dec_terminacao -- "Particípio (-do)" --> dec_part_atrativa{"Há palavra atrativa antes do Auxiliar?"}
  dec_terminacao -- "Gerúndio (-ndo) ou Infinitivo (-r)" --> dec_ger_inf_atrativa{"Há palavra atrativa antes do Auxiliar?"}
  dec_part_atrativa -- "Sim" --> res_part_com_atrativa["Próclise ao Auxiliar ou Solto no Meio"]
  dec_part_atrativa -- "Não" --> res_part_sem_atrativa["Auxiliar: Ênclise/Próclise ou Solto no Meio"]
  dec_ger_inf_atrativa -- "Sim" --> res_ger_inf_com_atrativa["Próclise ao Aux., Solto no Meio ou Ênclise ao Principal"]
  dec_ger_inf_atrativa -- "Não" --> res_ger_inf_sem_atrativa["Todas as Posições Padrão são Permitidas"]
